<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Basma Elmaimouni — Développeuse Web Full-Stack</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,500;0,9..144,600;0,9..144,700;1,9..144,500;1,9..144,600&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{
  --cream:#FFF7CD;
  --peach:#FDC3A1;
  --coral:#FB9B8F;
  --rose:#F57799;
  --paper:#FFFDF6;
  --ink:#3A2A38;
  --ink-soft:#7a6270;
  --ink-faint:#a4909c;
  --line: rgba(58,42,56,0.12);
  --shadow-soft: 0 20px 45px -20px rgba(245,119,153,0.35);
  --shadow-card: 0 14px 30px -18px rgba(58,42,56,0.22);
  --radius-lg: 28px;
  --radius-md: 18px;
  --radius-sm: 10px;
}
*{box-sizing:border-box; margin:0; padding:0;}
html{scroll-behavior:smooth;}
body{
  font-family:'Plus Jakarta Sans', sans-serif;
  color:var(--ink);
  background:var(--cream);
  overflow-x:hidden;
  line-height:1.6;
}
@media (prefers-reduced-motion: reduce){
  *{animation-duration:0.01ms !important; animation-iteration-count:1 !important; transition-duration:0.01ms !important; scroll-behavior:auto !important;}
}
::selection{background:var(--rose); color:var(--paper);}

a{color:inherit; text-decoration:none;}
ul{list-style:none;}
img{max-width:100%; display:block;}
section{position:relative;}
.wrap{max-width:1180px; margin:0 auto; padding:0 32px;}

h1,h2,h3,h4{font-family:'Fraunces', serif; font-weight:600; line-height:1.12; letter-spacing:-0.01em;}

.eyebrow{
  font-family:'JetBrains Mono', monospace;
  font-size:0.78rem;
  color:var(--rose);
  display:inline-flex;
  align-items:center;
  gap:8px;
  font-weight:500;
  margin-bottom:14px;
}
.eyebrow::before{
  content:"";
  width:22px; height:1px;
  background:var(--rose);
  display:inline-block;
}

/* ---------- background texture ---------- */
.blob{
  position:absolute;
  border-radius:50%;
  filter:blur(60px);
  opacity:0.55;
  z-index:0;
  pointer-events:none;
}

/* ---------- NAV ---------- */
header{
  position:fixed; top:0; left:0; right:0; z-index:100;
  background:rgba(255,247,205,0.72);
  backdrop-filter:blur(14px) saturate(140%);
  border-bottom:1px solid rgba(58,42,56,0.08);
  transition:box-shadow .3s ease;
}
header.scrolled{box-shadow:0 8px 24px -18px rgba(58,42,56,0.25);}
nav{
  max-width:1180px; margin:0 auto; padding:16px 32px;
  display:flex; align-items:center; justify-content:space-between;
}
.logo{
  font-family:'JetBrains Mono', monospace;
  font-weight:600;
  font-size:1.02rem;
  letter-spacing:-0.02em;
  display:flex; align-items:center; gap:2px;
}
.logo .cursor{
  display:inline-block; width:8px; height:1.1em; background:var(--rose);
  margin-left:3px; animation:blink 1.1s steps(1) infinite;
}
@keyframes blink{50%{opacity:0;}}
.navlinks{display:flex; gap:6px; align-items:center;}
.navlinks a{
  font-size:0.92rem; font-weight:600; padding:9px 15px; border-radius:100px;
  color:var(--ink-soft); position:relative; transition:color .25s ease;
}
.navlinks a:hover{color:var(--ink);}
.navlinks a.active{color:var(--ink); background:var(--paper); box-shadow: var(--shadow-card);}
.navlinks a.active::after{content:"";}
.nav-toggle{display:none;}

@media (max-width:860px){
  .navlinks{
    position:fixed; top:64px; right:24px; left:24px;
    background:var(--paper); border-radius:var(--radius-md);
    flex-direction:column; align-items:stretch; padding:10px;
    box-shadow: var(--shadow-card);
    transform:translateY(-12px); opacity:0; pointer-events:none;
    transition:all .25s ease;
  }
  .navlinks.open{transform:translateY(0); opacity:1; pointer-events:auto;}
  .navlinks a{text-align:left;}
  .nav-toggle{
    display:flex; flex-direction:column; gap:5px; background:none; border:none; cursor:pointer; padding:8px;
  }
  .nav-toggle span{width:22px; height:2px; background:var(--ink); border-radius:2px;}
}

/* ---------- HERO ---------- */
.hero{
  min-height:100vh;
  display:flex; align-items:center;
  padding:130px 0 80px;
}
.hero .wrap{
  display:grid; grid-template-columns:1.05fr 0.95fr; gap:60px; align-items:center;
}
.hero-tag{
  display:inline-flex; align-items:center; gap:10px;
  background:var(--paper); border:1px solid var(--line);
  padding:8px 16px 8px 8px; border-radius:100px;
  font-size:0.85rem; font-weight:600; color:var(--ink-soft);
  box-shadow:var(--shadow-card);
  margin-bottom:26px;
  transform:rotate(-1.5deg);
}
.hero-tag .flag{width:20px; height:20px; border-radius:50%; overflow:hidden; display:inline-flex; align-items:center; justify-content:center; background:var(--coral); font-size:11px;}
.hero h1{
  font-size:clamp(2.5rem, 5vw, 4.2rem);
  margin-bottom:22px;
}
.hero h1 em{font-style:italic; font-weight:500; color:var(--rose);}
.hero p.lead{
  font-size:1.12rem; color:var(--ink-soft); max-width:46ch; margin-bottom:34px;
}
.btn-row{display:flex; gap:14px; flex-wrap:wrap;}
.btn{
  font-family:'Plus Jakarta Sans', sans-serif;
  font-weight:700; font-size:0.95rem;
  padding:14px 26px; border-radius:100px;
  display:inline-flex; align-items:center; gap:8px;
  cursor:pointer; border:none; transition:transform .25s ease, box-shadow .25s ease;
}
.btn-primary{background:var(--rose); color:var(--paper); box-shadow:0 14px 30px -12px rgba(245,119,153,0.55);}
.btn-primary:hover{transform:translateY(-3px); box-shadow:0 18px 34px -10px rgba(245,119,153,0.6);}
.btn-ghost{background:transparent; color:var(--ink); border:1.5px solid var(--line);}
.btn-ghost:hover{border-color:var(--rose); color:var(--rose); transform:translateY(-3px);}

/* hero visual */
.hero-visual{position:relative; height:520px;}
.terminal{
  position:absolute; top:0; left:10px; width:min(430px, 92%);
  background:#3A2A38; border-radius:16px; overflow:hidden;
  box-shadow:0 30px 60px -20px rgba(58,42,56,0.45);
  transform:rotate(2deg);
}
.terminal-bar{
  display:flex; align-items:center; gap:7px;
  padding:12px 16px; background:#2f2130;
}
.terminal-bar span{width:11px; height:11px; border-radius:50%; display:inline-block;}
.terminal-bar span:nth-child(1){background:#FB9B8F;}
.terminal-bar span:nth-child(2){background:#FDC3A1;}
.terminal-bar span:nth-child(3){background:#FFF7CD;}
.terminal-bar .fname{margin-left:auto; font-family:'JetBrains Mono', monospace; font-size:0.72rem; color:#cbb8c6;}
.terminal-body{padding:22px 20px 30px; font-family:'JetBrains Mono', monospace; font-size:0.86rem; color:#e9dbe6; min-height:230px;}
.terminal-body .ln{color:#8f7a8d; user-select:none; display:inline-block; width:18px;}
.terminal-body .tag{color:#FB9B8F;}
.terminal-body .str{color:#FFF7CD;}
.terminal-body .fn{color:#FDC3A1;}
.terminal-body .cm{color:#8f7a8d;}
.terminal-body #typed-line{white-space:pre;}
.type-cursor{display:inline-block; width:7px; height:1em; background:var(--rose); vertical-align:middle; animation:blink 0.9s steps(1) infinite;}

.polaroid{
  position:absolute; bottom:0; right:0; width:250px;
  background:var(--paper); padding:12px 12px 46px;
  border-radius:14px; box-shadow:0 25px 50px -18px rgba(58,42,56,0.35);
  transform:rotate(-6deg);
  animation:float-slow 6s ease-in-out infinite;
}
.polaroid img{border-radius:8px; width:100%; aspect-ratio:1/1; object-fit:cover;}
.polaroid figcaption{
  font-family:'Fraunces', serif; font-style:italic; font-size:0.92rem;
  text-align:center; margin-top:12px; color:var(--ink-soft);
}
@keyframes float-slow{0%,100%{transform:rotate(-6deg) translateY(0);} 50%{transform:rotate(-4deg) translateY(-10px);}}

.chip-float{
  position:absolute; background:var(--paper); border-radius:12px;
  padding:9px 14px; font-size:0.78rem; font-weight:700; color:var(--ink);
  box-shadow:var(--shadow-card); display:flex; align-items:center; gap:6px;
  animation:float-slow2 5s ease-in-out infinite;
}
@keyframes float-slow2{0%,100%{transform:translateY(0) rotate(var(--r,0deg));} 50%{transform:translateY(-8px) rotate(var(--r,0deg));}}
.chip-1{top:14px; right:36%; background:var(--peach); --r:4deg; animation-delay:.3s;}
.chip-2{bottom:60px; left:0; background:var(--cream); --r:-3deg; animation-delay:1s;}

/* reveal on scroll */
.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}
.reveal.is-visible{opacity:1; transform:translateY(0);}

/* ---------- SECTION HEADERS ---------- */
.section{padding:120px 0;}
.section-head{max-width:640px; margin-bottom:60px;}
.section-head h2{font-size:clamp(2rem, 3.4vw, 2.8rem);}
.section-head p{color:var(--ink-soft); margin-top:14px; font-size:1.05rem;}

/* ---------- ABOUT ---------- */
#about{background:var(--paper);}
.about-grid{display:grid; grid-template-columns:0.85fr 1.15fr; gap:70px; align-items:center;}
.about-photo{position:relative;}
.about-photo .frame{
  border-radius:var(--radius-lg); overflow:hidden;
  box-shadow:var(--shadow-soft); border:6px solid var(--paper);
  outline:1px solid var(--line);
}
.about-photo .frame img{width:100%; aspect-ratio:4/5; object-fit:cover;}
.badge-float{
  position:absolute; background:var(--rose); color:var(--paper);
  border-radius:16px; padding:16px 18px; box-shadow:var(--shadow-soft);
  bottom:-26px; left:-26px; width:150px;
  font-family:'JetBrains Mono', monospace;
}
.badge-float .num{font-size:1.7rem; font-weight:700; font-family:'Fraunces', serif;}
.badge-float .lbl{font-size:0.72rem; opacity:0.9; margin-top:2px;}

.about-text h3{font-size:1.6rem; margin-bottom:6px;}
.about-text .role{color:var(--rose); font-weight:700; font-size:0.95rem; margin-bottom:18px; display:block;}
.about-text p{color:var(--ink-soft); margin-bottom:16px; max-width:60ch;}
.stat-row{display:flex; gap:14px; flex-wrap:wrap; margin-top:28px;}
.stat-chip{
  background:var(--cream); border-radius:var(--radius-md); padding:14px 18px;
  min-width:120px; box-shadow:var(--shadow-card);
}
.stat-chip:nth-child(2){transform:rotate(-1.5deg); background:var(--peach);}
.stat-chip:nth-child(3){transform:rotate(1.5deg); background:var(--coral); color:var(--paper);}
.stat-chip .num{font-family:'Fraunces', serif; font-weight:700; font-size:1.5rem;}
.stat-chip .lbl{font-size:0.78rem; color:inherit; opacity:0.85;}

/* ---------- MODULES ---------- */
#modules{background:var(--cream);}
.module-grid{display:grid; grid-template-columns:repeat(3, 1fr); gap:22px;}
.module-card{
  background:var(--paper); border-radius:var(--radius-md); padding:26px 24px;
  box-shadow:var(--shadow-card); border:1px solid var(--line);
  transition:transform .3s ease, box-shadow .3s ease;
}
.module-card:hover{transform:translateY(-6px); box-shadow:0 24px 40px -18px rgba(58,42,56,0.28);}
.module-top{display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:14px;}
.module-icon{
  width:42px; height:42px; border-radius:12px; display:flex; align-items:center; justify-content:center;
  font-size:1.2rem;
}
.module-card h4{font-size:1.12rem; margin-bottom:6px;}
.module-card p{font-size:0.9rem; color:var(--ink-soft); margin-bottom:18px;}
.tp-count{
  font-family:'JetBrains Mono', monospace; font-size:0.72rem; font-weight:600;
  color:var(--ink-faint); background:var(--cream); padding:4px 10px; border-radius:100px;
}
.tp-list{display:flex; flex-direction:column; gap:8px; margin-bottom:14px;}
.tp-item{
  display:flex; align-items:center; gap:9px; font-size:0.85rem; color:var(--ink);
  background:var(--cream); border-radius:9px; padding:8px 11px;
}
.tp-item .dot{width:6px; height:6px; border-radius:50%; background:var(--rose); flex:none;}
.tp-add{
  border:1.5px dashed var(--ink-faint); border-radius:9px; padding:8px 11px;
  font-size:0.82rem; color:var(--ink-faint); text-align:center; font-weight:600;
  cursor:default;
}

/* ---------- PROJECTS ---------- */
#projects{background:var(--paper);}
.project-grid{display:grid; grid-template-columns:1fr 1fr; gap:28px;}
.project-card{
  border-radius:var(--radius-lg); overflow:hidden; background:var(--cream);
  box-shadow:var(--shadow-card); border:1px solid var(--line);
}
.browser-bar{
  display:flex; align-items:center; gap:7px; padding:12px 16px; background:var(--ink);
}
.browser-bar span{width:10px; height:10px; border-radius:50%; background:rgba(255,255,255,0.25);}
.browser-bar .url{
  margin-left:10px; background:rgba(255,255,255,0.12); color:rgba(255,255,255,0.7);
  font-family:'JetBrains Mono', monospace; font-size:0.72rem; padding:4px 12px; border-radius:100px;
  flex:1;
}
.project-shot{
  height:200px; position:relative; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
}
.project-shot .code-mock{
  font-family:'JetBrains Mono', monospace; font-size:0.78rem; color:var(--paper);
  padding:22px; width:100%; height:100%; opacity:0.92;
}
.project-shot .code-mock div{margin-bottom:5px;}
.project-body{padding:26px 24px 30px;}
.project-body h4{font-size:1.3rem; margin-bottom:8px;}
.project-body p{color:var(--ink-soft); font-size:0.92rem; margin-bottom:18px;}
.tech-tags{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:20px;}
.tech-tags span{
  font-family:'JetBrains Mono', monospace; font-size:0.72rem; font-weight:600;
  background:var(--paper); border:1px solid var(--line); padding:5px 11px; border-radius:100px;
}
.project-links{display:flex; gap:16px;}
.project-links a{font-weight:700; font-size:0.88rem; color:var(--rose); display:inline-flex; align-items:center; gap:6px;}
.project-links a:hover{text-decoration:underline;}

/* ---------- SKILLS ---------- */
#skills{background:var(--cream);}
.skills-grid{display:grid; grid-template-columns:1fr 1fr; gap:50px 60px;}
.skill-group h4{
  font-family:'JetBrains Mono', monospace; font-size:0.85rem; letter-spacing:0.02em;
  color:var(--rose); margin-bottom:22px; font-weight:600;
}
.skill-item{margin-bottom:20px;}
.skill-item .top{display:flex; justify-content:space-between; font-size:0.9rem; font-weight:600; margin-bottom:8px;}
.skill-bar{height:9px; background:var(--paper); border-radius:100px; overflow:hidden; border:1px solid var(--line);}
.skill-fill{
  height:100%; width:0%; border-radius:100px; background:linear-gradient(90deg, var(--coral), var(--rose));
  transition:width 1.2s cubic-bezier(.22,.9,.3,1);
}

/* ---------- CONTACT ---------- */
#contact{background:var(--paper);}
.contact-grid{display:grid; grid-template-columns:1fr 0.9fr; gap:50px; align-items:start;}
.contact-card{
  background:var(--ink); color:var(--paper); border-radius:var(--radius-lg);
  padding:44px 40px;
}
.contact-card h3{font-size:1.7rem; margin-bottom:10px; color:var(--paper);}
.contact-card p{color:rgba(255,253,246,0.7); margin-bottom:30px; max-width:42ch;}
.contact-list{display:flex; flex-direction:column; gap:16px;}
.contact-list a{
  display:flex; align-items:center; gap:14px; font-weight:600; font-size:0.98rem;
  padding:14px 16px; border-radius:14px; background:rgba(255,253,246,0.06);
  transition:background .25s ease, transform .25s ease;
}
.contact-list a:hover{background:rgba(255,253,246,0.14); transform:translateX(4px);}
.contact-list .ico{
  width:36px; height:36px; border-radius:10px; background:var(--rose);
  display:flex; align-items:center; justify-content:center; flex:none; font-size:1rem;
}
.notebook{
  background:var(--cream); border-radius:var(--radius-lg); padding:34px 32px;
  box-shadow:var(--shadow-card); position:relative; transform:rotate(1deg);
}
.notebook::before{
  content:""; position:absolute; left:26px; top:0; bottom:0; width:1px; background:rgba(245,119,153,0.35);
}
.notebook h4{font-family:'Fraunces', serif; font-style:italic; font-size:1.3rem; margin-bottom:18px; padding-left:18px;}
.notebook ul{display:flex; flex-direction:column; gap:13px; padding-left:18px;}
.notebook li{display:flex; align-items:center; gap:10px; font-size:0.95rem;}
.notebook .check{
  width:19px; height:19px; border-radius:6px; background:var(--rose); flex:none;
  display:flex; align-items:center; justify-content:center; color:var(--paper); font-size:0.7rem;
}

/* ---------- FOOTER ---------- */
footer{
  background:var(--ink); color:rgba(255,253,246,0.6);
  text-align:center; padding:34px 20px; font-size:0.85rem;
}
footer strong{color:var(--paper);}

/* ---------- RESPONSIVE ---------- */
@media (max-width:980px){
  .hero .wrap{grid-template-columns:1fr; text-align:left;}
  .hero-visual{height:440px; margin-top:20px;}
  .about-grid, .contact-grid{grid-template-columns:1fr; gap:40px;}
  .about-photo{max-width:360px;}
  .module-grid{grid-template-columns:repeat(2,1fr);}
  .project-grid{grid-template-columns:1fr;}
  .skills-grid{grid-template-columns:1fr;}
}
@media (max-width:560px){
  .wrap{padding:0 20px;}
  .section{padding:80px 0;}
  .module-grid{grid-template-columns:1fr;}
  .terminal{width:100%;}
  .polaroid{width:190px;}
}
</style>
</head>
<body>

<header id="siteHeader">
  <nav>
    <a href="#home" class="logo">basma.dev<span class="cursor"></span></a>
    <button class="nav-toggle" id="navToggle" aria-label="Menu"><span></span><span></span><span></span></button>
    <ul class="navlinks" id="navLinks">
      <li><a href="#home" class="nav-link">Home</a></li>
      <li><a href="#about" class="nav-link">About</a></li>
      <li><a href="#modules" class="nav-link">Modules</a></li>
      <li><a href="#projects" class="nav-link">Projects</a></li>
      <li><a href="#skills" class="nav-link">Skills</a></li>
      <li><a href="#contact" class="nav-link">Contact</a></li>
    </ul>
  </nav>
</header>

<!-- ================= HOME ================= -->
<section id="home" class="hero">
  <div class="blob" style="width:480px; height:480px; background:var(--coral); top:-120px; right:-140px;"></div>
  <div class="blob" style="width:360px; height:360px; background:var(--peach); bottom:-100px; left:-120px; opacity:0.4;"></div>
  <div class="wrap">
    <div class="hero-copy">
      <div class="hero-tag"><span class="flag">🇲🇦</span> ISTA NTIC Tanger · 2ᵉ année Full-Stack</div>
      <h1>Future développeuse <em>full-stack</em>,<br>un projet à la fois.</h1>
      <p class="lead">Je suis Basma Elmaimouni — étudiante en développement web full-stack, curieuse, organisée, et déterminée à transformer chaque atelier en compétence solide.</p>
      <div class="btn-row">
        <a href="#projects" class="btn btn-primary">Voir mes projets</a>
        <a href="#contact" class="btn btn-ghost">Me contacter</a>
      </div>
    </div>
    <div class="hero-visual">
      <div class="terminal">
        <div class="terminal-bar"><span></span><span></span><span></span><div class="fname">portfolio.js</div></div>
        <div class="terminal-body">
          <div><span class="ln">1</span><span class="cm">// à propos de moi</span></div>
          <div><span class="ln">2</span><span class="fn">const</span> basma = {</div>
          <div><span class="ln">3</span>&nbsp;&nbsp;role: <span class="str">"Étudiante Full-Stack"</span>,</div>
          <div><span class="ln">4</span>&nbsp;&nbsp;ville: <span class="str">"Tanger, Maroc"</span>,</div>
          <div><span class="ln">5</span>&nbsp;&nbsp;stack: [<span class="str">"HTML"</span>, <span class="str">"CSS"</span>, <span class="str">"JS"</span>, <span class="str">"PHP"</span>]</div>
          <div><span class="ln">6</span>};</div>
          <div>&nbsp;</div>
          <div><span class="ln">7</span><span id="typed-line"></span><span class="type-cursor"></span></div>
        </div>
      </div>
      <figure class="polaroid">
        <img src="data:image/jpeg;base64," alt="Basma Elmaimouni à son bureau de développeuse">
        <figcaption>code · coffee · progrès</figcaption>
      </figure>
      <div class="chip-float chip-1">Build Something Great ♡</div>
      <div class="chip-float chip-2">Tu peux le faire ♡</div>
    </div>
  </div>
</section>

<!-- ================= ABOUT ================= -->
<section id="about" class="section">
  <div class="wrap about-grid">
    <div class="about-photo reveal">
      <div class="frame"><img src="data:image/jpeg;base64," alt="Basma Elmaimouni, développeuse web"></div>
      <div class="badge-float">
        <div class="num">2ᵉ</div>
        <div class="lbl">année Full-Stack Web Dev</div>
      </div>
    </div>
    <div class="about-text reveal">
      <span class="eyebrow">à propos</span>
      <h3>Salut, moi c'est Basma 👋</h3>
      <span class="role">Développeuse web en formation · ISTA NTIC Tanger</span>
